import{_ as t,o as a,c as r,ak as i}from"./chunks/framework.B8jO0odJ.js";const u=JSON.parse('{"title":"Chainy draft learner and teacher guide","description":"Capstone project title: Chainy: A 3D World Educational Game for learning emerging Technology (Blockchain & AI)","frontmatter":{"title":"Chainy draft learner and teacher guide","description":"Capstone project title: Chainy: A 3D World Educational Game for learning emerging Technology (Blockchain & AI)","source":"docs/user-guide.md","category":"Guides & tooling","sourceUpdated":null,"outline":[2,3]},"headers":[],"relativePath":"content/docs/user-guide.md","filePath":"content/docs/user-guide.md"}'),o={name:"content/docs/user-guide.md"};function n(s,e,d,l,c,h){return a(),r("div",null,[...e[0]||(e[0]=[i('<div><h1 id="chainy-draft-learner-and-teacher-guide">Chainy draft learner and teacher guide<a class="header-anchor" href="#chainy-draft-learner-and-teacher-guide" aria-label="Link to this section">​</a></h1><p><strong>Capstone project title:</strong> Chainy: A 3D World Educational Game for learning emerging Technology (Blockchain &amp; AI)</p><p>This guide describes the proposed interface. The game is not yet implemented; verify labels and steps against the actual pilot APK before using this as Appendix D.</p><h2 id="learner-use">Learner use<a class="header-anchor" href="#learner-use" aria-label="Link to this section">​</a></h2><ol><li>Open the installed game. Enter the study and learner code given by the teacher. Do not use a name, birthday or another learner&#39;s code.</li><li>On first use, confirm that a new local profile will be created. A returning code resumes only progress stored on this device.</li><li>Try the short tap/select/confirm tutorial if this is your first time using the controls. Choose Continue or a lesson in Web3, Blockchain or AI on the map. Read the short objective.</li><li>Tap choices or select a supplied record and its destination to arrange/link it. Follow the activity&#39;s visible instructions, then select Test or Check. Walking and a movement joystick are not required.</li><li>Inspect feedback, revise the arrangement and retry. Hints explain the concept; they do not change the historical record of earlier attempts.</li><li>Complete the lesson check, read explanations and return to the map. Saved progress and badges record completion; they do not by themselves establish learning improvement.</li><li>Before handing the device to someone else, use Switch learner from the menu with the teacher&#39;s help.</li></ol><p>English text supplies the essential instructions even when audio is muted. The proposed interface provides text/icon feedback alongside color and buttons for actions that would otherwise require precise dragging.</p><h2 id="teacher-preparation-and-collection">Teacher preparation and collection<a class="header-anchor" href="#teacher-preparation-and-collection" aria-label="Link to this section">​</a></h2><p>Use the approved build and content version for the study. Maintain the authorized participant/code procedure and any separate identity mapping outside the game. Explain that the code selects a profile; it is not a verified online account.</p><p>Before each session check the device, available storage, learner code and frozen assessment version. Do the pre-assessment before instruction when required by the approved protocol. Keep assistance consistent and record interruptions.</p><p>After the session, open the staff export screen, select the intended study/session scope, check the record count, and save the package through the system file picker. Transfer it through the agreed staff-controlled method. Verify the import receipt and accepted/duplicate/rejected counts. Do not delete local evidence merely because export was attempted. Actual receipt and the retention policy govern deletion.</p><p>Downloading/distributing the APK, installing an update and collecting evidence are separate tasks. Gameplay can remain offline even if a teacher later uploads the exported file using another application.</p><h2 id="common-situations">Common situations<a class="header-anchor" href="#common-situations" aria-label="Link to this section">​</a></h2><table><thead><tr><th>Situation</th><th>Expected response</th></tr></thead><tbody><tr><td>Code is mistyped</td><td>Show format feedback; confirm before creating a new profile</td></tr><tr><td>Code is used on another phone</td><td>A local profile may be created; existing progress does not automatically follow</td></tr><tr><td>Shared device shows another learner</td><td>Switch profile before starting; do not merge results based on device label</td></tr><tr><td>App closes during play</td><td>Resume the last safely committed checkpoint; interrupted attempts remain identifiable</td></tr><tr><td>Save fails or storage is full</td><td>Keep a clear error and retry path; do not display completion before a successful save</td></tr><tr><td>Export is canceled or fails</td><td>Local records stay available; select a destination and retry</td></tr><tr><td>Package is imported again</td><td>Importer recognizes existing event IDs and does not duplicate totals</td></tr><tr><td>Device is lost or app is uninstalled</td><td>Previously received exports remain with the custodian; learner code alone cannot recover unexported local data</td></tr><tr><td>An update is needed</td><td>Use the approved signed update and tested migration process; do not uninstall to update</td></tr></tbody></table><h2 id="support-and-handover">Support and handover<a class="header-anchor" href="#support-and-handover" aria-label="Link to this section">​</a></h2><p>Report the app/build version, device model/Android version, affected level, steps and visible error without placing learner records in GitHub. Sherwin coordinates reports, Christian handles technical failures, Miguel reproduces UI issues and Sean handles evaluation-record questions. Use the approved private evidence location for participant-related details.</p><p>Before distribution, replace this draft&#39;s proposed interface wording with tested instructions and screenshots from the actual build. The release checklist is in <a href="/Chainy-Docs/content/docs/qa-evaluation.html">QA and evaluation</a>.</p></div>',1)])])}const f=t(o,[["render",n]]);export{u as __pageData,f as default};
